using BootstrapBlazor.Components;

using Newtonsoft.Json;

namespace ThingsGateway.Gateway.Application;

/// <summary>
/// 报警变量
/// </summary>
public class AlarmVariable : PrimaryIdEntity, IDBHistoryAlarm
{
    /// <inheritdoc  cref="Variable.Name"/>
    [OrmColumn(ColumnDescription = "变量名称", IsNullable = false)]
    [AutoGenerateColumn(Visible = true, Filterable = true, Sortable = true)]
    public string Name { get; set; }

    /// <inheritdoc  cref="Variable.Description"/>
    [OrmColumn(ColumnDescription = "描述", IsNullable = true)]
    [AutoGenerateColumn(Visible = true, Filterable = true, Sortable = true)]
    [JsonProperty(NullValueHandling = NullValueHandling.Ignore)]
    [System.Text.Json.Serialization.JsonIgnore(Condition = System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull)]
    public string? Description { get; set; }

    /// <inheritdoc  cref="IBaseDataEntity.CreateOrgId"/>
    [OrmColumn(ColumnDescription = "组织Id", IsNullable = true)]
    [AutoGenerateColumn(Visible = false, Filterable = true, Sortable = true)]
    public long CreateOrgId { get; set; }

    /// <inheritdoc  cref="IBaseEntity.CreateUserId"/>
    [OrmColumn(ColumnDescription = "创建用户Id", IsNullable = true)]
    [AutoGenerateColumn(Visible = false, Filterable = true, Sortable = true)]
    public long CreateUserId { get; set; }

    /// <inheritdoc  cref="Variable.DeviceId"/>
    [OrmColumn(ColumnDescription = "设备Id", IsNullable = true)]
    [AutoGenerateColumn(Visible = false, Filterable = true, Sortable = true)]
    public long DeviceId { get; set; }

    /// <inheritdoc  cref="VariableRuntime.DeviceName"/>
    [OrmColumn(ColumnDescription = "设备名称", IsNullable = true)]
    [AutoGenerateColumn(Visible = true, Filterable = true, Sortable = true)]
    public string DeviceName { get; set; }

    /// <inheritdoc  cref="Variable.RegisterAddress"/>
    [OrmColumn(ColumnDescription = "变量地址")]
    [AutoGenerateColumn(Visible = true, Filterable = true, Sortable = true)]
    [JsonProperty(NullValueHandling = NullValueHandling.Ignore)]
    [System.Text.Json.Serialization.JsonIgnore(Condition = System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull)]
    public string RegisterAddress { get; set; }

    /// <inheritdoc  cref="Variable.DataType"/>
    [OrmColumn(ColumnDescription = "数据类型")]
    [AutoGenerateColumn(Visible = true, Filterable = true, Sortable = true)]
    public DataTypeEnum DataType { get; set; }

    /// <inheritdoc  cref="AlarmPropertys.AlarmLevel"/>
    [OrmColumn(ColumnDescription = "报警等级", IsNullable = false)]
    [AutoGenerateColumn(Visible = true, Filterable = true, Sortable = true)]
    public int AlarmLevel { get; set; }

    /// <inheritdoc  cref="AlarmRuntimePropertys.AlarmCode"/>
    [OrmColumn(ColumnDescription = "报警值", IsNullable = false)]
    [AutoGenerateColumn(Visible = true, Filterable = true, Sortable = true)]
    public string AlarmCode { get; set; }

    /// <inheritdoc  cref="AlarmRuntimePropertys.AlarmLimit"/>
    [OrmColumn(ColumnDescription = "报警限值", IsNullable = false)]
    [AutoGenerateColumn(Visible = true, Filterable = true, Sortable = true)]
    public string AlarmLimit { get; set; }

    /// <inheritdoc  cref="AlarmRuntimePropertys.AlarmText"/>
    [OrmColumn(ColumnDescription = "报警文本", IsNullable = true)]
    [AutoGenerateColumn(Visible = true, Filterable = true, Sortable = true)]
    public string? AlarmText { get; set; }

    /// <inheritdoc  cref="AlarmRuntimePropertys.RecoveryCode"/>
    [OrmColumn(ColumnDescription = "恢复值", IsNullable = false)]
    [AutoGenerateColumn(Visible = true, Filterable = true, Sortable = true)]
    public string RecoveryCode { get; set; }

    /// <inheritdoc  cref="AlarmRuntimePropertys.AlarmTime"/>
    [OrmColumn(ColumnDescription = "报警时间", IsNullable = false)]
    [AutoGenerateColumn(Visible = true, Filterable = true, Sortable = true)]
    public DateTime AlarmTime { get; set; }


    /// <inheritdoc  cref="AlarmRuntimePropertys.EventTime"/>
    [OrmColumn(ColumnDescription = "事件时间", IsNullable = false)]
    [AutoGenerateColumn(Visible = true, Filterable = true, Sortable = true)]
    [TimeDbSplitField(DateType.Month)]
    public DateTime EventTime { get; set; }

    /// <inheritdoc  cref="AlarmRuntimePropertys.FinishTime"/>
    [OrmColumn(ColumnDescription = "恢复时间", IsNullable = false)]
    [AutoGenerateColumn(Visible = true, Filterable = true, Sortable = true)]
    [TimeDbSplitField(DateType.Month)]
    public DateTime FinishTime { get; set; }

    /// <inheritdoc  cref="AlarmRuntimePropertys.ConfirmTime"/>
    [OrmColumn(ColumnDescription = "确认时间", IsNullable = false)]
    [AutoGenerateColumn(Visible = true, Filterable = true, Sortable = true)]
    [TimeDbSplitField(DateType.Month)]
    public DateTime ConfirmTime { get; set; }

    /// <inheritdoc  cref="AlarmRuntimePropertys.AlarmType"/>
    [OrmColumn(ColumnDescription = "报警类型", IsNullable = false)]
    [AutoGenerateColumn(Visible = true, Filterable = true, Sortable = true)]
    public AlarmTypeEnum? AlarmType { get; set; }

    /// <inheritdoc  cref="AlarmRuntimePropertys.EventType"/>
    [OrmColumn(ColumnDescription = "事件类型", IsNullable = false)]
    [AutoGenerateColumn(Visible = true, Filterable = true, Sortable = true)]
    public EventTypeEnum EventType { get; set; }

    /// <inheritdoc cref="Variable.Remark1"/>
    [JsonProperty(NullValueHandling = NullValueHandling.Ignore)]
    [System.Text.Json.Serialization.JsonIgnore(Condition = System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull)]
    public string Remark1 { get; set; }

    /// <inheritdoc cref="Variable.Remark2"/>
    [JsonProperty(NullValueHandling = NullValueHandling.Ignore)]
    [System.Text.Json.Serialization.JsonIgnore(Condition = System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull)]
    public string Remark2 { get; set; }

    /// <inheritdoc cref="Variable.Remark3"/>
    [JsonProperty(NullValueHandling = NullValueHandling.Ignore)]
    [System.Text.Json.Serialization.JsonIgnore(Condition = System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull)]
    public string Remark3 { get; set; }

    /// <inheritdoc cref="Variable.Remark4"/>
    [JsonProperty(NullValueHandling = NullValueHandling.Ignore)]
    [System.Text.Json.Serialization.JsonIgnore(Condition = System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull)]
    public string Remark4 { get; set; }

    /// <inheritdoc cref="Variable.Remark5"/>
    [JsonProperty(NullValueHandling = NullValueHandling.Ignore)]
    [System.Text.Json.Serialization.JsonIgnore(Condition = System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull)]
    public string Remark5 { get; set; }
}
